import type { Candle } from '../types/market';

function unpackHourly(tuples: [string, number, number, number, number, number][]): Candle[] {
  return tuples.map(t => ({
    time: t[0],
    open: t[1],
    high: t[2],
    low: t[3],
    close: t[4],
    volume: t[5]
  }));
}

